            if a[i-1]==3 { ans += 2; }
            else { ans += 3; }
        }
        else if a[i]==2 && a[i+1]==1 {
            ans += 3;
        }
        else if a[i]==1 && a[i+1]==3 {
            ans += 4;
        }
        else if a[i]==3 && a[i+1]==1 {
            ans += 4;
        }
        else {
            puts!("Infinite\n");
            return;
        }
    }
    puts!("Finite\n");
    puts!("{}\n", ans);

}

